+		path := strings.ToLower(symbol.FilePath)
+		base := strings.TrimSuffix(strings.ToLower(filepath.Base(path)), strings.ToLower(filepath.Ext(path)))
+		score := relationScores[symbol.ID]
+		switch strings.ToLower(symbol.Kind) {
