+
+func retrievalSiblingImplementationCandidates(testFile string) []string {
+	ext := filepath.Ext(testFile)
+	switch {
+	case strings.HasSuffix(testFile, "_test.go"):
+		return []string{strings.TrimSuffix(testFile, "_test.go") + ".go"}
